$s=recibo_settings();$rows=array();$summary=array();$error='';
try {$db=recibo_db();$q=$db->query('SELECT envio,COUNT(*) AS total FROM brl_pago GROUP BY envio');if($q)while($r=$q->fetch_assoc())$summary[$r['envio']]=$r['total'];
 $q=$db->query('SELECT p.*,d.http_code,d.message_id FROM brl_pago p LEFT JOIN vpscloud_recibo_delivery d ON d.queue_id=p.id ORDER BY p.data DESC,p.id DESC LIMIT 100');if($q)while($r=$q->fetch_assoc())$rows[]=$r;$db->close();}catch(Exception $e){$error=$e->getMessage();}
function rh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$labels=array(0=>'Pendente',1=>'Aceito pela API',2=>'Revisar envio',3=>'Falhou / ignorado',4=>'Descartado sem envio');
?><!doctype html><html lang="pt-BR" class="has-navbar-fixed-top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recibo Evolution</title><link href="../../estilos/mk-auth.css" rel="stylesheet"><link href="../../estilos/font-awesome.css" rel="stylesheet"><link href="../../estilos/bi-icons.css" rel="stylesheet"><script src="../../scripts/jquery.js"></script><script src="../../scripts/mk-auth.js"></script>
<style>.recibo{font:15px system-ui;color:#253748;max-width:1250px;margin:30px auto;padding:0 18px}.recibo section{padding:24px;border:1px solid #d9e3ea;border-radius:12px;background:white;margin:20px 0;box-shadow:0 3px 14px #152f4410}.recibo h1{font-size:25px}.recibo h2{font-size:19px}.recibo label{display:block;margin:15px 0 6px}.recibo input:not([type=checkbox]),.recibo textarea{box-sizing:border-box;width:100%;padding:11px;border:1px solid #bccbd5;border-radius:6px;font:inherit}.recibo textarea{min-height:330px}.recibo button{padding:10px 16px;border:0;border-radius:6px;background:#15895b;color:white;cursor:pointer;margin:8px 8px 0 0;font:inherit}.recibo button:disabled{opacity:.5;cursor:wait}.recibo .secondary{background:#42647e}.recibo .warning{color:#9b4b00}.recibo .hint{color:#596e7d;font-size:14px}.recibo table{border-collapse:collapse;width:100%;font-size:13px}.recibo th,.recibo td{text-align:left;padding:10px;border-bottom:1px solid #dde5eb}.recibo th{background:#eaf3ee}.recibo pre{white-space:pre-wrap;word-break:break-word;max-height:320px;overflow:auto;background:#f3f6f8;padding:15px}.recibo code{word-break:break-word}.recibo #feedback{position:fixed;bottom:20px;right:24px;max-width:650px;background:#16374b;color:white;padding:16px;border-radius:8px;z-index:9999}.recibo #feedback:empty{display:none}.recibo .scroll{overflow:auto}.recibo .receipt-switch{display:inline-flex;align-items:center;gap:12px;cursor:pointer;font-weight:600}.receipt-switch input{position:absolute;opacity:0;width:1px;height:1px}.receipt-switch-track{display:inline-block;width:76px;height:42px;border-radius:30px;background:#697b88;position:relative}.receipt-switch-track:before{content:"";position:absolute;width:34px;height:34px;border-radius:50%;background:white;top:4px;left:4px;box-shadow:0 1px 4px #0004}.receipt-switch input:checked+.receipt-switch-track{background:#15895b}.receipt-switch input:checked+.receipt-switch-track:before{left:38px}.receipt-switch input:focus-visible+.receipt-switch-track{outline:3px solid #1677bb;outline-offset:3px}.receipt-switch input:disabled+.receipt-switch-track{opacity:.5;cursor:wait}.recibo #receiptControl{border-left:7px solid #6b7784;background:#f2f5f8}.recibo #receiptControl[data-enabled="1"]{border-left-color:#15895b;background:#effaf4}.recibo #receiptControl h2{font-size:23px;font-weight:700}.recibo #receiptSwitchLabel{font-size:21px}.recibo .receipt-switch{padding:12px 16px;background:white;border-radius:10px;border:1px solid #b9cad4}.recibo select{display:block;box-sizing:border-box;width:100%;padding:12px;font:inherit;font-size:16px;background:white;border:1px solid #9cb3c1;border-radius:7px;margin-top:7px}.recibo #discardScope{border:2px solid #ad7800;background:#fff9ed;font-weight:600}</style></head><body>
<?php include __DIR__.'/../../topo.php'; ?>
<main class="recibo"><h1>Recibo Evolution</h1><p>Confirmações de pagamento pelo WhatsApp.</p>
<section id="receiptControl" data-enabled="<?=$s['receipts_enabled']?'1':'0'?>"><h2 id="receiptMasterStatus">Envios de comprovantes: <?=$s['receipts_enabled']?'ativados':'desativados'?></h2><p>Use este único interruptor para ativar ou desativar os comprovantes. Desligado bloqueia envios automáticos, manuais e retroativos, preservando conexão, template e histórico. Um envio já iniciado pode concluir. O teste com dados fictícios continua disponível.</p><label class="receipt-switch"><input type="checkbox" role="switch" id="toggleReceipts" aria-label="Ativar envios de comprovantes" aria-checked="<?=$s['receipts_enabled']?'true':'false'?>" data-enabled="<?=$s['receipts_enabled']?'1':'0'?>" <?=$s['receipts_enabled']?'checked':''?>><span class="receipt-switch-track" aria-hidden="true"></span><span id="receiptSwitchLabel"><?=$s['receipts_enabled']?'Ativado':'Desativado'?></span></label></section><?php if($error):?><p class="warning"><?=rh($error)?></p><?php endif;?>
<section><h2>Resumo</h2><p><?php foreach($labels as $k=>$label)echo rh($label).': <strong>'.rh(isset($summary[$k])?$summary[$k]:0).'</strong> &nbsp; ';?></p><p class="hint">A página mostra no máximo os 100 registros mais recentes. “Aceito pela API” não comprova leitura ou entrega no destinatário.</p><button type="button" onclick="document.getElementById('templateBox').hidden=false;document.getElementById('templateBox').scrollIntoView({behavior:'smooth'})">Editar template da mensagem</button></section>
<form id="settings" method="post" action="api.php"><input type="hidden" name="csrf" value="<?=rh($_SESSION['recibo_csrf'])?>"><input type="hidden" name="action" value="save">
<section><h2>Conexão e agendamento</h2><button type="button" class="secondary" id="importNative">Usar servidor WhatsApp do MK-AUTH</button><p class="hint">Importa e salva servidor, instância e token cadastrados em Opções → WhatsApp → Servidor. O token permanece oculto. Não ativa o envio automático.</p><label>URL da API<input name="api_url" value="<?=rh($s['api_url'])?>" required placeholder="http://127.0.0.1:7070"></label><label>Nome da instância<input name="instance" value="<?=rh($s['instance'])?>" required maxlength="100"></label><label>Token / API Key<input type="password" name="token" autocomplete="new-password" placeholder="<?=empty($s['token'])?'Informe a chave':'Chave salva · vazio mantém o valor atual'?>"></label><label>Nome do provedor<input name="provider" value="<?=rh($s['provider'])?>" maxlength="120"></label><label>Intervalo em minutos<input name="interval" type="number" min="1" max="60" value="<?=rh($s['interval'])?>"></label><p class="hint">Retomada protegida: somente pagamentos do dia atual, um recibo por execução. Pendentes anteriores são marcados como descartados sem envio ao retomar com a instância conectada. O cron verifica a cada minuto, respeitando o intervalo escolhido. Execuções concorrentes são bloqueadas. Só processa pagamentos capturados pela fila do addon.</p><button type="submit">Salvar configurações</button></section>
<section id="templateBox" hidden><h2>Template do recibo</h2><p class="hint">Campos disponíveis: <code>{cliente} {cpf_cnpj} {id_pagamento} {data_pagamento} {data_vencimento} {valor} {valor_pago} {coletor} {forma_pagamento} {provedor}</code>.</p><textarea name="template" id="template" required><?=rh($s['template'])?></textarea><button type="button" id="preview">Pré-visualizar sem enviar</button><button type="submit">Salvar template</button><pre id="previewText" hidden></pre></section></form>
<section><h2>Envio real de teste</h2><p class="hint">Envia somente um exemplo com dados fictícios ao número informado, usando conexão e template já salvos. Não usa clientes nem consome recibos da fila. Use seu próprio número ou de alguém que concordou com o teste.</p><label>Número de teste<input id="testPhone" type="tel" placeholder="55 + DDD + número" autocomplete="off"></label><button type="button" id="sendTest">Enviar teste para este número</button></section><section><h2>Processamento</h2><label>Descarte de pendentes<select id="discardScope"><option value="all">Descartar todos os pendentes atuais</option><option value="before_today">Descartar anteriores a hoje — manter os de hoje</option></select></label><p class="hint">Considera a data de pagamento e o dia atual no banco do servidor. Registros sem data entram no descarte de anteriores. Confira a opção antes de confirmar.</p><p class="warning">Descartar o acúmulo reduz o volume de mensagens antigas e evita liberar uma lista grande de recibos. Isso pode reduzir situações associadas a denúncias e bloqueios, mas não garante que o WhatsApp não bloqueará o número. Envie apenas mensagens esperadas por quem autorizou o contato.</p><button type="button" id="run">Enviar próximo recibo pendente</button><button type="button" class="secondary" id="discard">Descartar recibos pendentes sem enviar</button><button type="button" class="secondary" id="refresh">Atualizar página</button><p class="warning">Descartar retira somente os pendentes atuais da fila e preserva o histórico; não envia mensagens nem altera os pagamentos. Novos pagamentos continuam sendo capturados. Ações manuais enviam apenas um recibo por vez. Registros em revisão não são reenviados automaticamente: uma falha de rede pode ter acontecido depois de a API aceitar a mensagem.</p></section>
<section><h2>Confirmação retroativa — envio individual</h2><p class="hint">O automático envia somente pagamentos do dia atual, um por execução. Para o fim de semana ou uma interrupção, consulte até 3 dias anteriores e escolha um único recibo. Pendentes e descartados sem envio podem ser selecionados. Já aceitos pela API, falhas e envios em revisão não são incluídos. Esta ação envia uma mensagem real ao cliente selecionado.</p><label>Período<select id="retroDays"><option value="1">Último 1 dia anterior</option><option value="2">Últimos 2 dias anteriores</option><option value="3">Últimos 3 dias anteriores</option></select></label><button type="button" class="secondary" id="listRetro">Consultar retroativos — sem enviar</button><label>Recibo<select id="retroReceipt" disabled><option value="">Consulte o período primeiro</option></select></label><button type="button" id="sendRetro" disabled>Enviar somente o recibo selecionado</button><p class="hint">Consulte novamente após cada envio. Não existe opção de envio retroativo em lote.</p></section><section><h2>Últimos registros</h2><div class="scroll"><table><thead><tr><th>ID</th><th>Registro</th><th>Login</th><th>Pagamento</th><th>Valor pago</th><th>Estado</th><th>HTTP</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=rh($r['id'])?></td><td><?=rh($r['data'])?></td><td><?=rh($r['login'])?></td><td><?=rh($r['datapag'])?></td><td>R$ <?=rh(number_format($r['valorpag'],2,',','.'))?></td><td><?=rh(isset($labels[$r['envio']])?$labels[$r['envio']]:'Desconhecido')?></td><td><?=rh($r['http_code'])?></td><td><?php if(in_array((int)$r['envio'],array(2,3),true)):?><button type="button" class="secondary" data-retry="<?=rh($r['id'])?>">Revisar e recolocar</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section><h2>Log recente</h2><p class="hint">Visualização limitada aos últimos 64 KiB. Os logs são rotacionados; nenhuma limpeza automática de pagamentos pendentes é executada.</p><button type="button" class="secondary" id="clear">Limpar log</button><pre><?=rh(recibo_tail(RECIBO_DATA.'/log_pagamentos.txt'))?></pre></section><p id="feedback" role="status"></p></main>
<?php include __DIR__.'/../../baixo.php'; ?><script src="../../menu.js.hhvm"></script>
<script>
const form=document.getElementById('settings'),csrf=form.elements.csrf.value;function feedback(s){document.getElementById('feedback').textContent=s}
async function request(data,button){if(button){button.disabled=true}try{const r=await fetch('api.php',{method:'POST',body:data});const raw=await r.text();let o;try{o=JSON.parse(raw)}catch{throw Error(r.status===401||/Acesso negado/i.test(raw)?'Sessão expirada. Entre novamente pelo MK-AUTH e atualize a página.':'Resposta inesperada do servidor. Atualize a página e tente novamente.')} if(!r.ok)throw Error(o.error||'Falha na operação');feedback(o.message||'Concluído.');return o}catch(e){feedback(e.message);throw e}finally{if(button)button.disabled=false}}
function payload(action){const d=new FormData();d.set('csrf',csrf);d.set('action',action);return d}
form.onsubmit=e=>{e.preventDefault();request(new FormData(form),e.submitter||form.querySelector('button')).catch(()=>{})};
document.getElementById('toggleReceipts').onchange=async function(){const wasEnabled=this.dataset.enabled==='1',enable=this.checked;if(enable&&!confirm('Ativar envios de comprovantes? O automático retomará somente os pagamentos do dia atual, um por execução.')){this.checked=wasEnabled;return}const d=payload('set_receipts_enabled');d.set('enabled',enable?'1':'0');try{const o=await request(d,this);this.dataset.enabled=o.enabled?'1':'0';this.checked=o.enabled;const card=document.getElementById('receiptControl');if(card)card.dataset.enabled=o.enabled?'1':'0';this.setAttribute('aria-checked',o.enabled?'true':'false');document.getElementById('receiptSwitchLabel').textContent=o.enabled?'Ativado':'Desativado';document.getElementById('receiptMasterStatus').textContent='Envios de comprovantes: '+(o.enabled?'ativados':'desativados')}catch{this.checked=wasEnabled;this.setAttribute('aria-checked',wasEnabled?'true':'false')}};
document.getElementById('importNative').onclick=async function(){if(!confirm('Importar e salvar a conexão WhatsApp cadastrada no MK-AUTH? Template e agendamento serão preservados.'))return;try{const o=await request(payload('import_native'),this);form.elements.api_url.value=o.api_url;form.elements.instance.value=o.instance;form.elements.token.value='';form.elements.token.placeholder='Chave importada · vazio mantém o valor atual'}catch{}};
document.getElementById('preview').onclick=async function(){const d=payload('preview');d.set('template',form.elements.template.value);try{const o=await request(d,this),p=document.getElementById('previewText');p.textContent=o.preview;p.hidden=false;feedback('Prévia de exemplo. Nenhuma mensagem foi enviada.')}catch{}};
document.getElementById('run').onclick=async function(){if(!confirm('Enviar o próximo recibo pendente pela instância configurada? Confira o número conectado.'))return;try{await request(payload('run'),this)}catch{}};
document.getElementById('sendTest').onclick=function(){const phone=document.getElementById('testPhone').value;if(!phone.trim()){feedback('Informe o número de teste.');return}if(!confirm('Enviar UMA mensagem REAL com dados fictícios para '+phone+'? Será usada a conexão salva. A fila não será alterada.'))return;const d=payload('send_test');d.set('test_phone',phone);d.set('confirm_test','ENVIAR_TESTE');request(d,this).catch(()=>{})};
const retroDays=document.getElementById('retroDays'),retroReceipt=document.getElementById('retroReceipt'),sendRetro=document.getElementById('sendRetro');let loadedRetroDays='';
retroDays.onchange=()=>{loadedRetroDays='';retroReceipt.replaceChildren(new Option('Consulte o período novamente',''));retroReceipt.disabled=true;sendRetro.disabled=true};
document.getElementById('listRetro').onclick=async function(){const d=payload('list_retro');d.set('days',retroDays.value);sendRetro.disabled=true;try{const o=await request(d,this);loadedRetroDays=retroDays.value;retroReceipt.replaceChildren(new Option(o.rows.length?'Selecione um recibo':'Nenhum retroativo elegível',''));o.rows.forEach(r=>retroReceipt.add(new Option('ID '+r.id+' · '+r.datapag+' · R$ '+r.valorpag,r.id)));retroReceipt.disabled=!o.rows.length}catch{}};
retroReceipt.onchange=()=>{sendRetro.disabled=!retroReceipt.value||loadedRetroDays!==retroDays.value};
sendRetro.onclick=async function(){const id=retroReceipt.value;if(!id||loadedRetroDays!==retroDays.value)return;if(!confirm('Enviar UMA confirmação REAL ao cliente do recibo ID '+id+'? Não será enviado um lote. Confira se ele já recebeu por outro canal.'))return;const d=payload('send_retro');d.set('days',loadedRetroDays);d.set('id',id);d.set('confirm_retro','ENVIAR_UM');try{await request(d,this)}catch{}finally{retroDays.onchange()}};
document.getElementById('discard').onclick=function(){if(!confirm('Descartar os recibos da opção selecionada SEM ENVIAR? O histórico e os pagamentos serão preservados. Novos pagamentos continuarão entrando na fila.'))return;const d=payload('discard_pending');d.set('scope',document.getElementById('discardScope').value);d.set('confirm_discard','DESCARTAR');request(d,this).then(o=>{alert(o.message);location.reload()}).catch(()=>{})};
document.getElementById('refresh').onclick=()=>location.reload();document.getElementById('clear').onclick=function(){if(confirm('Limpar somente o arquivo de log do addon?'))request(payload('clear_log'),this).then(()=>location.reload()).catch(()=>{})};
document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{if(!confirm('Confira o envio anterior. Recolocar pode gerar duplicidade se o cliente já recebeu. Deseja continuar?'))return;const d=payload('retry');d.set('id',b.dataset.retry);d.set('confirm_retry','1');request(d,b).then(()=>location.reload()).catch(()=>{})});
</script></body></html>
